<template>
  <view class="page">
    <jk-page-nav title="登记线下销售" />
    <view class="content">
      <view class="notice">确认后的销售会真实扣减你的库存。经营毛利与平台佣金分开计算，高额、匿名或缺少凭证的销售需要后台审核。</view>
      <view class="card">
        <view class="section-title">客户信息</view>
        <view class="type-row"><view v-for="x in customerTypes" :key="x.value" :class="{active:form.customerType===x.value}" @tap="changeCustomerType(x.value)">{{x.label}}</view></view>
        <view class="field"><text>客户手机号</text><input v-model.trim="customerPhone" type="number" maxlength="11" :placeholder="form.customerType==='ANONYMOUS'?'用于风控，仅脱敏保存':'输入注册手机号后点击核验'"/><button v-if="form.customerType!=='ANONYMOUS'" size="mini" @tap="resolveCustomer">核验</button></view>
        <view v-if="resolvedCustomer" class="resolved">已关联：{{resolvedCustomer.name}} {{resolvedCustomer.phone}}</view>
      </view>

      <view class="card">
        <view class="section-head"><view class="section-title">销售商品</view><text @tap="stockVisible=true">从库存添加 ›</text></view>
        <view v-for="(item,index) in form.items" :key="item.productId+'-'+item.skuId" class="sale-item">
          <image :src="item.image||'/static/jk-ui-v2/products/glucose-paper.png'" mode="aspectFill"/>
          <view class="item-main"><strong>{{item.productName||('商品'+item.productId)}}</strong><small>{{item.skuCode||item.skuName||item.skuId}} · 可用 {{item.availableQty}}</small><view class="inputs"><text>数量</text><input v-model.number="item.quantity" type="number"/><text>单价</text><input v-model.number="item.unitPrice" type="digit"/></view></view>
          <text class="remove" @tap="removeItem(index)">×</text>
        </view>
        <jk-empty v-if="!form.items.length" text="请从本人真实库存中添加商品"/>
        <view v-if="form.items.length" class="total">共 {{totalQty}} 件　成交金额 <strong>¥{{money(totalAmount)}}</strong></view>
      </view>

      <view class="card">
        <view class="section-title">收款与凭证</view>
        <picker :range="payMethods" range-key="label" @change="selectPay"><view class="picker-row"><text>收款方式</text><span>{{payMethodLabel}} ›</span></view></picker>
        <view class="upload-title">销售/收款凭证 <small>选填；金额较高时建议上传</small></view>
        <payment-voucher-upload v-model="voucherUrl"/>
        <view class="field"><text>推广来源</text><input v-model.trim="form.promotionSource" placeholder="如社区活动、老客转介绍（选填）"/></view>
      </view>
      <button class="submit" :disabled="submitting" @tap="submit">{{submitting?'提交中...':'确认登记'}}</button>
    </view>

    <view v-if="stockVisible" class="mask" @tap="stockVisible=false"></view>
    <view class="stock-sheet" :class="{show:stockVisible}">
      <view class="sheet-head"><strong>选择库存商品</strong><text @tap="stockVisible=false">完成</text></view>
      <view class="stock-list"><view v-for="item in stockItems" :key="item.productId+'-'+item.skuId" class="stock-row" @tap="addStock(item)"><image :src="item.productImage||item.image||'/static/jk-ui-v2/products/glucose-paper.png'"/><view><strong>{{item.productName||('商品'+item.productId)}}</strong><small>{{item.skuCode||item.skuName||item.skuId}}</small><text>可用 {{available(item)}} · 参考价 ¥{{money(item.referencePrice||item.price)}}</text></view><span>＋</span></view></view>
    </view>
  </view>
</template>
<script>
import JkPageNav from '@/components/jk/jk-page-nav.vue';import JkEmpty from '@/components/jk/jk-empty.vue';import paymentVoucherUpload from '@/components/jk/payment-voucher-upload.vue';
import {getJkMyStock} from '@/api/jk.js';import {resolveJkOfflineCustomer,createJkOfflineSale} from '@/api/jkV31.js';
export default{components:{JkPageNav,JkEmpty,paymentVoucherUpload},data(){return{form:{customerType:'REGISTERED_OLD',customerUserId:null,registeredCustomer:true,payMethod:'WECHAT',promotionSource:'',items:[]},customerPhone:'',resolvedCustomer:null,voucherUrl:'',stock:{items:[]},stockVisible:false,submitting:false,customerTypes:[{label:'老客户',value:'REGISTERED_OLD'},{label:'新客户',value:'REGISTERED_NEW'},{label:'匿名客户',value:'ANONYMOUS'}],payMethods:[{label:'微信收款',value:'WECHAT'},{label:'支付宝',value:'ALIPAY'},{label:'现金',value:'CASH'},{label:'银行卡',value:'BANK'}]}},computed:{stockItems(){return(this.stock.items||this.stock.records||[]).filter(x=>this.available(x)>0)},totalQty(){return this.form.items.reduce((s,x)=>s+Number(x.quantity||0),0)},totalAmount(){return this.form.items.reduce((s,x)=>s+Number(x.quantity||0)*Number(x.unitPrice||0),0)},payMethodLabel(){const x=this.payMethods.find(i=>i.value===this.form.payMethod);return x?x.label:'请选择'}},created(){this.loadStock()},onLoad(){this.loadStock()},methods:{loadStock(){getJkMyStock().then(r=>this.stock=r.data||r||{items:[]})},available(x){return Number(x.availableQuantity!==undefined?x.availableQuantity:(x.availableQty!==undefined?x.availableQty:(x.stockQuantity||0)))},money(v){const n=Number(v||0);return Number.isNaN(n)?String(v||0):n.toFixed(2)},changeCustomerType(v){this.form.customerType=v;this.form.registeredCustomer=v!=='ANONYMOUS';this.form.customerUserId=null;this.resolvedCustomer=null},resolveCustomer(){if(!/^1\d{10}$/.test(this.customerPhone))return this.$util.Tips({title:'请输入完整11位手机号'});resolveJkOfflineCustomer(this.customerPhone).then(r=>{const d=r.data||r||{};this.resolvedCustomer=d;this.form.customerUserId=d.userId;this.$util.Tips({title:'客户核验成功'})})},addStock(x){if(this.form.items.some(i=>i.productId===x.productId&&i.skuId===x.skuId))return this.$util.Tips({title:'该规格已添加'});this.form.items.push({productId:x.productId,skuId:x.skuId,productName:x.productName,skuName:x.skuName,skuCode:x.skuCode,image:x.productImage||x.image,availableQty:this.available(x),quantity:1,unitPrice:Number(x.referencePrice||x.price||0)});this.stockVisible=false},removeItem(i){this.form.items.splice(i,1)},selectPay(e){this.form.payMethod=this.payMethods[Number(e.detail.value)].value},submit(){if(this.form.customerType!=='ANONYMOUS'&&!this.form.customerUserId)return this.$util.Tips({title:'请先核验注册客户'});if(this.form.customerType==='ANONYMOUS'&&!/^1\d{10}$/.test(this.customerPhone))return this.$util.Tips({title:'匿名客户需填写完整手机号'});if(!this.form.items.length)return this.$util.Tips({title:'请添加销售商品'});for(const x of this.form.items){if(!x.quantity||x.quantity<1||x.quantity>x.availableQty)return this.$util.Tips({title:'销售数量不正确'});if(!x.unitPrice||x.unitPrice<=0)return this.$util.Tips({title:'成交单价必须大于0'})}const payload={requestNo:'OFFLINE-'+Date.now()+'-'+Math.random().toString(36).slice(2,8),customerType:this.form.customerType,customerUserId:this.form.customerUserId,customerName:this.resolvedCustomer&&this.resolvedCustomer.name,customerPhone:this.customerPhone,registeredCustomer:this.form.registeredCustomer,payMethod:this.form.payMethod,saleTime:new Date(),voucherUrls:this.voucherUrl?[this.voucherUrl]:[],promotionSource:this.form.promotionSource,items:this.form.items.map(x=>({productId:x.productId,skuId:x.skuId,quantity:Number(x.quantity),unitPrice:Number(x.unitPrice)}))};this.submitting=true;createJkOfflineSale(payload).then(r=>{const d=r.data||r||{};this.$util.Tips({title:d.status==='PENDING_AUDIT'?'已提交后台审核':'销售登记成功'});setTimeout(()=>uni.redirectTo({url:'/pages/jk/trade/list?mode=offlineSaleDetail&id='+d.id}),500)}).finally(()=>this.submitting=false)}}};
</script>
<style scoped>.page{min-height:100vh;background:#f7f9f9}.content{padding:18rpx 22rpx 40rpx}.notice{padding:18rpx 20rpx;border-radius:16rpx;background:#fff8e8;color:#9a6a13;font-size:21rpx;line-height:1.6}.card{margin-top:18rpx;padding:22rpx;border-radius:20rpx;background:#fff}.section-title{color:#1f2937;font-size:28rpx;font-weight:700}.section-head{display:flex;align-items:center;justify-content:space-between}.section-head>text{color:#10a981;font-size:22rpx}.type-row{display:flex;gap:12rpx;margin-top:18rpx}.type-row view{flex:1;padding:16rpx 0;border:1rpx solid #dce7e4;border-radius:14rpx;text-align:center;color:#6f7d82;font-size:22rpx}.type-row view.active{border-color:#10b981;background:#edfdf8;color:#0d9e7c;font-weight:700}.field{display:flex;align-items:center;min-height:78rpx;margin-top:14rpx;border-bottom:1rpx solid #edf1f0}.field>text{width:150rpx;color:#58666c;font-size:22rpx}.field input{flex:1;font-size:22rpx}.field button{height:54rpx;margin:0;padding:0 18rpx;background:#10b981;color:#fff;font-size:20rpx;line-height:54rpx}.resolved{margin-top:12rpx;padding:12rpx;border-radius:10rpx;background:#eefbf7;color:#0d9e7c;font-size:21rpx}.sale-item{display:flex;align-items:center;min-height:132rpx;border-bottom:1rpx solid #edf1f0}.sale-item>image{width:90rpx;height:90rpx;border-radius:12rpx}.item-main{min-width:0;flex:1;margin-left:14rpx}.item-main strong,.item-main small{display:block}.item-main strong{font-size:24rpx}.item-main small{margin-top:5rpx;color:#859197;font-size:19rpx}.inputs{display:flex;align-items:center;gap:6rpx;margin-top:10rpx}.inputs text{font-size:19rpx;color:#7d898f}.inputs input{width:90rpx;height:46rpx;padding:0 8rpx;border-radius:8rpx;background:#f4f7f6;font-size:20rpx}.remove{padding:16rpx;color:#ef5b4c;font-size:36rpx}.total{padding-top:16rpx;text-align:right;color:#657278;font-size:21rpx}.total strong{color:#10b981;font-size:27rpx}.picker-row{display:flex;align-items:center;justify-content:space-between;height:76rpx;border-bottom:1rpx solid #edf1f0;color:#5b686e;font-size:22rpx}.picker-row span{color:#10a981}.upload-title{margin:18rpx 0 12rpx;font-size:22rpx}.upload-title small{color:#929da2;font-size:18rpx}.submit{height:84rpx;margin-top:22rpx;border-radius:42rpx;background:#10b981;color:#fff;font-size:27rpx;line-height:84rpx}.mask{position:fixed;z-index:80;inset:0;background:rgba(0,0,0,.45)}.stock-sheet{position:fixed;z-index:81;right:0;bottom:-75vh;left:0;height:70vh;border-radius:28rpx 28rpx 0 0;background:#fff;transition:.25s}.stock-sheet.show{bottom:0}.sheet-head{display:flex;align-items:center;justify-content:space-between;padding:24rpx;border-bottom:1rpx solid #eee}.sheet-head text{color:#10b981}.stock-list{height:calc(70vh - 90rpx);padding:0 22rpx;overflow-y:auto}.stock-row{display:flex;align-items:center;min-height:130rpx;border-bottom:1rpx solid #edf1f0}.stock-row image{width:88rpx;height:88rpx;border-radius:12rpx}.stock-row>view{display:flex;min-width:0;flex:1;flex-direction:column;gap:5rpx;margin-left:13rpx}.stock-row strong{font-size:23rpx}.stock-row small,.stock-row text{color:#839096;font-size:19rpx}.stock-row span{color:#10b981;font-size:40rpx}</style>
